use split_decls_genesis :: ourprelude :: * ; use crate :: cell :: Cell ; use crate :: ops :: { Deref , DerefMut } ; #[doc = " Pads and aligns a value to the length of a cache line."] #[derive (Clone , Copy , Default , Hash , PartialEq , Eq)] #[cfg_attr (any (target_arch = "x86_64" , target_arch = "aarch64" , target_arch = "powerpc64" ,) , repr (align (128)))] #[cfg_attr (any (target_arch = "arm" , target_arch = "mips" , target_arch = "mips32r6" , target_arch = "mips64" , target_arch = "mips64r6" ,) , repr (align (32)))] #[cfg_attr (target_arch = "s390x" , repr (align (256)))] #[cfg_attr (not (any (target_arch = "x86_64" , target_arch = "aarch64" , target_arch = "powerpc64" , target_arch = "arm" , target_arch = "mips" , target_arch = "mips32r6" , target_arch = "mips64" , target_arch = "mips64r6" , target_arch = "s390x" ,)) , repr (align (64)))] pub struct CachePadded < T > { value : T , } impl < T > CachePadded < T > { #[doc = " Pads and aligns a value to the length of a cache line."] pub fn new (value : T) -> CachePadded < T > { CachePadded :: < T > { value } } } impl < T > Deref for CachePadded < T > { type Target = T ; fn deref (& self) -> & T { & self . value } } impl < T > DerefMut for CachePadded < T > { fn deref_mut (& mut self) -> & mut T { & mut self . value } } const SPIN_LIMIT : u32 = 6 ; #[doc = " Performs quadratic backoff in spin loops."] pub struct Backoff { step : Cell < u32 > , } impl Backoff { #[doc = " Creates a new `Backoff`."] pub fn new () -> Self { Backoff { step : Cell :: new (0) } } #[doc = " Backs off using lightweight spinning."] #[doc = ""] #[doc = " This method should be used for retrying an operation because another thread made"] #[doc = " progress. i.e. on CAS failure."] #[inline] pub fn spin_light (& self) { let step = self . step . get () . min (SPIN_LIMIT) ; for _ in 0 .. step . pow (2) { crate :: hint :: spin_loop () ; } self . step . set (self . step . get () + 1) ; } #[doc = " Backs off using heavyweight spinning."] #[doc = ""] #[doc = " This method should be used in blocking loops where parking the thread is not an option."] #[inline] pub fn spin_heavy (& self) { if self . step . get () <= SPIN_LIMIT { for _ in 0 .. self . step . get () . pow (2) { crate :: hint :: spin_loop () } } else { crate :: thread :: yield_now () ; } self . step . set (self . step . get () + 1) ; } }